SELECT "line_id", "request_number", "item", "quantity", "unit_price", "line_value", "reason", "requested_resolution", "requested_variant", "customer", "customer_email", "order_number", "requested_date", "delivered_date", "in_window", "item_on_order", "share", "item_on_hand", "variant_on_hand", "request_value", "route", 'request above the care threshold' AS "verdict_reason"
FROM (SELECT "t39"."line_id", "t39"."request_number", "t39"."item", "t39"."quantity", "t39"."unit_price", "t39"."line_value", "t39"."reason", "t39"."requested_resolution", "t39"."requested_variant", "t39"."customer", "t39"."customer_email", "t39"."order_number", "t39"."requested_date", "t39"."delivered_date", "t39"."in_window", "t39"."item_on_order", "t39"."share", "t39"."item_on_hand", "t39"."variant_on_hand", "t42"."request_value", CASE WHEN "t39"."delivered_date" IS NULL OR "t39"."item_on_order" = 0 THEN 'reject_not_ours' WHEN "t39"."in_window" = 0 THEN 'reject_late' WHEN "t39"."share" > :abuse_share THEN 'reject_abuse' WHEN "t42"."request_value" > :care_threshold THEN 'to_customer_care' WHEN "t39"."line_value" < :small_value AND "t39"."reason" IN ('damaged', 'did_not_arrive') THEN 'refund_no_return' WHEN "t39"."reason" IN ('damaged', 'did_not_arrive') AND "t39"."item_on_hand" >= "t39"."quantity" THEN 'replacement_no_return' WHEN "t39"."requested_resolution" = 'exchange' AND "t39"."variant_on_hand" >= "t39"."quantity" THEN 'exchange' ELSE 'refund_after_return' END AS "route"
        FROM (SELECT "t23"."line_id", "t23"."request_number", "t23"."item", "t23"."quantity", "t23"."unit_price", "t23"."line_value", "t23"."reason", "t23"."requested_resolution", "t23"."requested_variant", "t23"."customer", "t23"."customer_email", "t23"."order_number", "t23"."requested_date", "t23"."delivered_date", "t23"."in_window", "t23"."item_on_order", "t23"."share", "t38"."item_on_hand", "t38"."variant_on_hand"
                FROM (SELECT "t9"."line_id", "t9"."request_number", "t9"."item", "t9"."quantity", "t9"."unit_price", "t9"."line_value", "t9"."reason", "t9"."requested_resolution", "t9"."requested_variant", "t9"."customer", "t9"."customer_email", "t9"."order_number", "t9"."requested_date", "t9"."delivered_date", "t9"."in_window", "t9"."item_on_order", "t22"."share"
                        FROM (SELECT "t2"."line_id", "t2"."request_number", "t2"."item", "t2"."quantity", "t2"."unit_price", "t2"."line_value", "t2"."reason", "t2"."requested_resolution", "t2"."requested_variant", "t2"."customer", "t2"."customer_email", "t2"."order_number", "t2"."requested_date", "t8"."delivered_date", "t8"."in_window", "t8"."item_on_order"
                                FROM (SELECT "line_id", "request_number", "item", "quantity", "unit_price", "quantity" * "unit_price" AS "line_value", "reason", "requested_resolution", "requested_variant", "customer0" AS "customer", "email" AS "customer_email", "order_number", "requested_date"
                                        FROM (SELECT "t"."line_id", "t"."request_number", "t"."line_no", "t"."item", "t"."quantity", "t"."unit_price", "t"."reason", "t"."requested_resolution", "t"."requested_variant", "t"."state", "t"."way", "t"."customer", "t"."customer0", "t"."order_number", "t"."channel", "t"."requested_date", "t"."state0", "customer"."customer_id", "customer"."addr", "customer"."cdemo", "customer"."hdemo", "customer"."birth_year", "customer"."center", "customer"."email"
                                                FROM (SELECT "return_request_line"."line_id", "return_request_line"."request_number", "return_request_line"."line_no", "return_request_line"."item", "return_request_line"."quantity", "return_request_line"."unit_price", "return_request_line"."reason", "return_request_line"."requested_resolution", "return_request_line"."requested_variant", "return_request_line"."state", "return_request_line"."way", "return_request_line"."customer", "return_request"."customer" AS "customer0", "return_request"."order_number", "return_request"."channel", "return_request"."requested_date", "return_request"."state" AS "state0"
                                                        FROM "return_request_line"
                                                            INNER JOIN "return_request" ON "return_request_line"."request_number" = "return_request"."request_number") AS "t"
                                                    LEFT JOIN "customer" ON "t"."customer" = "customer"."sk") AS "t0"
                                        WHERE "t0"."state" = 'received') AS "t2"
                                    LEFT JOIN (SELECT "t7"."line_id", "t7"."delivered_date", CASE WHEN "t7"."delivered_date" >= :as_of_minus_return_window_days THEN 1 ELSE 0 END AS "in_window", CASE WHEN "sales_line"."item" IS NULL THEN 0 ELSE 1 END AS "item_on_order"
                                        FROM (SELECT "t6"."line_id", "t6"."request_number", "t6"."item", "t6"."quantity", "t6"."unit_price", "t6"."line_value", "t6"."reason", "t6"."requested_resolution", "t6"."requested_variant", "t6"."customer", "t6"."customer_email", "t6"."order_number", "t6"."requested_date", "order"."channel", "order"."placed_date", "order"."delivered_date", "order"."fulfilling_warehouse", "order"."value", "order"."state", "order"."held_for", "order"."placed_by"
                                                FROM (SELECT "line_id", "request_number", "item", "quantity", "unit_price", "quantity" * "unit_price" AS "line_value", "reason", "requested_resolution", "requested_variant", "customer0" AS "customer", "email" AS "customer_email", "order_number", "requested_date"
                                                        FROM (SELECT "t3"."line_id", "t3"."request_number", "t3"."line_no", "t3"."item", "t3"."quantity", "t3"."unit_price", "t3"."reason", "t3"."requested_resolution", "t3"."requested_variant", "t3"."state", "t3"."way", "t3"."customer", "t3"."customer0", "t3"."order_number", "t3"."channel", "t3"."requested_date", "t3"."state0", "customer0"."customer_id", "customer0"."addr", "customer0"."cdemo", "customer0"."hdemo", "customer0"."birth_year", "customer0"."center", "customer0"."email"
                                                                FROM (SELECT "return_request_line0"."line_id", "return_request_line0"."request_number", "return_request_line0"."line_no", "return_request_line0"."item", "return_request_line0"."quantity", "return_request_line0"."unit_price", "return_request_line0"."reason", "return_request_line0"."requested_resolution", "return_request_line0"."requested_variant", "return_request_line0"."state", "return_request_line0"."way", "return_request_line0"."customer", "return_request0"."customer" AS "customer0", "return_request0"."order_number", "return_request0"."channel", "return_request0"."requested_date", "return_request0"."state" AS "state0"
                                                                        FROM "return_request_line" AS "return_request_line0"
                                                                            INNER JOIN "return_request" AS "return_request0" ON "return_request_line0"."request_number" = "return_request0"."request_number") AS "t3"
                                                                    LEFT JOIN "customer" AS "customer0" ON "t3"."customer" = "customer0"."sk") AS "t4"
                                                        WHERE "t4"."state" = 'received') AS "t6"
                                                    LEFT JOIN "order" ON "t6"."order_number" = "order"."order_number" AND "t6"."customer" = "order"."customer") AS "t7"
                                            LEFT JOIN "sales_line" ON "t7"."order_number" = "sales_line"."order_number" AND "t7"."item" = "sales_line"."item") AS "t8" ON "t2"."line_id" = "t8"."line_id") AS "t9"
                            LEFT JOIN (SELECT "t19"."line_id", COALESCE("t19"."returned_value", 0) / NULLIF("t21"."bought_value", 0) AS "share"
                                FROM (SELECT "t13"."line_id", "t13"."request_number", "t13"."item", "t13"."quantity", "t13"."unit_price", "t13"."line_value", "t13"."reason", "t13"."requested_resolution", "t13"."requested_variant", "t13"."customer", "t13"."customer_email", "t13"."order_number", "t13"."requested_date", "t18"."returned_value"
                                        FROM (SELECT "line_id", "request_number", "item", "quantity", "unit_price", "quantity" * "unit_price" AS "line_value", "reason", "requested_resolution", "requested_variant", "customer0" AS "customer", "email" AS "customer_email", "order_number", "requested_date"
                                                FROM (SELECT "t10"."line_id", "t10"."request_number", "t10"."line_no", "t10"."item", "t10"."quantity", "t10"."unit_price", "t10"."reason", "t10"."requested_resolution", "t10"."requested_variant", "t10"."state", "t10"."way", "t10"."customer", "t10"."customer0", "t10"."order_number", "t10"."channel", "t10"."requested_date", "t10"."state0", "customer1"."customer_id", "customer1"."addr", "customer1"."cdemo", "customer1"."hdemo", "customer1"."birth_year", "customer1"."center", "customer1"."email"
                                                        FROM (SELECT "return_request_line1"."line_id", "return_request_line1"."request_number", "return_request_line1"."line_no", "return_request_line1"."item", "return_request_line1"."quantity", "return_request_line1"."unit_price", "return_request_line1"."reason", "return_request_line1"."requested_resolution", "return_request_line1"."requested_variant", "return_request_line1"."state", "return_request_line1"."way", "return_request_line1"."customer", "return_request1"."customer" AS "customer0", "return_request1"."order_number", "return_request1"."channel", "return_request1"."requested_date", "return_request1"."state" AS "state0"
                                                                FROM "return_request_line" AS "return_request_line1"
                                                                    INNER JOIN "return_request" AS "return_request1" ON "return_request_line1"."request_number" = "return_request1"."request_number") AS "t10"
                                                            LEFT JOIN "customer" AS "customer1" ON "t10"."customer" = "customer1"."sk") AS "t11"
                                                WHERE "t11"."state" = 'received') AS "t13"
                                            LEFT JOIN (SELECT "customer", SUM("quantity" * "unit_price") AS "returned_value"
                                                FROM (SELECT "return_request_line2"."line_id", "return_request_line2"."request_number", "return_request_line2"."line_no", "return_request_line2"."item", "return_request_line2"."quantity", "return_request_line2"."unit_price", "return_request_line2"."reason", "return_request_line2"."requested_resolution", "return_request_line2"."requested_variant", "return_request_line2"."state", "return_request_line2"."way", "return_request_line2"."customer", "return_request2"."customer" AS "customer0", "return_request2"."order_number", "return_request2"."channel", "return_request2"."requested_date", "return_request2"."state" AS "state0"
                                                        FROM "return_request_line" AS "return_request_line2"
                                                            INNER JOIN "return_request" AS "return_request2" ON "return_request_line2"."request_number" = "return_request2"."request_number") AS "t14"
                                                WHERE "t14"."requested_date" >= :as_of_minus_365_days AND "t14"."state" <> 'rejected'
                                                GROUP BY "customer") AS "t18" ON "t13"."customer" = "t18"."customer") AS "t19"
                                    LEFT JOIN (SELECT "customer", SUM("ext_sales_price") AS "bought_value"
                                        FROM "sales_line"
                                        WHERE "sold_date" >= :as_of_minus_365_days
                                        GROUP BY "customer") AS "t21" ON "t19"."customer" = "t21"."customer") AS "t22" ON "t9"."line_id" = "t22"."line_id") AS "t23"
                    LEFT JOIN (SELECT "t33"."line_id", "t33"."item_on_hand", COALESCE("t37"."quantity_on_hand", 0) AS "variant_on_hand"
                        FROM (SELECT "t28"."line_id", "t28"."request_number", "t28"."item", "t28"."quantity", "t28"."unit_price", "t28"."line_value", "t28"."reason", "t28"."requested_resolution", "t28"."requested_variant", "t28"."customer", "t28"."customer_email", "t28"."order_number", "t28"."requested_date", "t28"."customer_id", "t28"."addr", "t28"."cdemo", "t28"."hdemo", "t28"."birth_year", "t28"."center", "t28"."email", "t32"."as_of_date", "t32"."quantity_on_hand", "t32"."_ttrp_g_n31_0", "t32"."_ttrp_g_n31_1", COALESCE("t32"."quantity_on_hand", 0) AS "item_on_hand"
                                FROM (SELECT "t27"."line_id", "t27"."request_number", "t27"."item", "t27"."quantity", "t27"."unit_price", "t27"."line_value", "t27"."reason", "t27"."requested_resolution", "t27"."requested_variant", "t27"."customer", "t27"."customer_email", "t27"."order_number", "t27"."requested_date", "customer3"."customer_id", "customer3"."addr", "customer3"."cdemo", "customer3"."hdemo", "customer3"."birth_year", "customer3"."center", "customer3"."email"
                                        FROM (SELECT "line_id", "request_number", "item", "quantity", "unit_price", "quantity" * "unit_price" AS "line_value", "reason", "requested_resolution", "requested_variant", "customer0" AS "customer", "email" AS "customer_email", "order_number", "requested_date"
                                                FROM (SELECT "t24"."line_id", "t24"."request_number", "t24"."line_no", "t24"."item", "t24"."quantity", "t24"."unit_price", "t24"."reason", "t24"."requested_resolution", "t24"."requested_variant", "t24"."state", "t24"."way", "t24"."customer", "t24"."customer0", "t24"."order_number", "t24"."channel", "t24"."requested_date", "t24"."state0", "customer2"."customer_id", "customer2"."addr", "customer2"."cdemo", "customer2"."hdemo", "customer2"."birth_year", "customer2"."center", "customer2"."email"
                                                        FROM (SELECT "return_request_line3"."line_id", "return_request_line3"."request_number", "return_request_line3"."line_no", "return_request_line3"."item", "return_request_line3"."quantity", "return_request_line3"."unit_price", "return_request_line3"."reason", "return_request_line3"."requested_resolution", "return_request_line3"."requested_variant", "return_request_line3"."state", "return_request_line3"."way", "return_request_line3"."customer", "return_request3"."customer" AS "customer0", "return_request3"."order_number", "return_request3"."channel", "return_request3"."requested_date", "return_request3"."state" AS "state0"
                                                                FROM "return_request_line" AS "return_request_line3"
                                                                    INNER JOIN "return_request" AS "return_request3" ON "return_request_line3"."request_number" = "return_request3"."request_number") AS "t24"
                                                            LEFT JOIN "customer" AS "customer2" ON "t24"."customer" = "customer2"."sk") AS "t25"
                                                WHERE "t25"."state" = 'received') AS "t27"
                                            INNER JOIN "customer" AS "customer3" ON "t27"."customer" = "customer3"."sk") AS "t28"
                                    LEFT JOIN (SELECT "t29"."as_of_date", "t29"."item", "t29"."warehouse", "t29"."quantity_on_hand", "t29"."_ttrp_g_n31_0", "t29"."_ttrp_g_n31_1"
                                        FROM (SELECT "as_of_date", "item", "warehouse", "quantity_on_hand", CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END AS "_ttrp_g_n31_0", CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END AS "_ttrp_g_n31_1"
                                                FROM "inventory") AS "t29"
                                            INNER JOIN (SELECT CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END AS "_ttrp_g_n31_0", CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END AS "_ttrp_g_n31_1", MAX("as_of_date") AS "_ttrp_latest_n31"
                                                FROM "inventory"
                                                GROUP BY CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END, CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END) AS "t31" ON "t29"."_ttrp_g_n31_0" = "t31"."_ttrp_g_n31_0" AND "t29"."_ttrp_g_n31_1" = "t31"."_ttrp_g_n31_1" AND "t29"."as_of_date" = "t31"."_ttrp_latest_n31") AS "t32" ON "t28"."item" = "t32"."item" AND "t28"."center" = "t32"."warehouse") AS "t33"
                            LEFT JOIN (SELECT "t34"."as_of_date", "t34"."item", "t34"."warehouse", "t34"."quantity_on_hand", "t34"."_ttrp_g_n31_0", "t34"."_ttrp_g_n31_1"
                                FROM (SELECT "as_of_date", "item", "warehouse", "quantity_on_hand", CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END AS "_ttrp_g_n31_0", CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END AS "_ttrp_g_n31_1"
                                        FROM "inventory") AS "t34"
                                    INNER JOIN (SELECT CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END AS "_ttrp_g_n31_0", CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END AS "_ttrp_g_n31_1", MAX("as_of_date") AS "_ttrp_latest_n31"
                                        FROM "inventory"
                                        GROUP BY CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END, CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END) AS "t36" ON "t34"."_ttrp_g_n31_0" = "t36"."_ttrp_g_n31_0" AND "t34"."_ttrp_g_n31_1" = "t36"."_ttrp_g_n31_1" AND "t34"."as_of_date" = "t36"."_ttrp_latest_n31") AS "t37" ON "t33"."requested_variant" = "t37"."item" AND "t33"."center" = "t37"."warehouse") AS "t38" ON "t23"."line_id" = "t38"."line_id") AS "t39"
            LEFT JOIN (SELECT "request_number", SUM("quantity" * "unit_price") AS "request_value"
                FROM "return_request_line"
                GROUP BY "request_number") AS "t42" ON "t39"."request_number" = "t42"."request_number") AS "t43"
WHERE "t43"."route" = 'to_customer_care'
